#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>

using namespace std;

using ll = long long;

int main() {
    vector<ll> degs(20);
    degs[1] = 1;
    for (int i = 1; i <= 17; ++i)
        degs[i + 1] = degs[i] * 10 + 1;

    ll n;
    cin >> n;

    // Iterative DP approach using stack simulation
    struct State {
        ll cur;
        int d;
        bool processed;
        ll result;
    };

    vector<State> stack;
    stack.push_back({abs(n), 18, false, 0});

    while (!stack.empty()) {
        auto& top = stack.back();
        if (top.processed) {
            stack.pop_back();
            continue;
        }

        if (top.cur % degs[top.d] == 0) {
            top.result = top.cur / degs[top.d] * top.d;
            top.processed = true;
            continue;
        }

        ll k = top.cur / degs[top.d];
        stack.push_back({top.cur - k * degs[top.d], top.d - 1, false, 0});
        stack.push_back({(k + 1) * degs[top.d] - top.cur, top.d - 1, false, 0});

        top.processed = true;
    }

    // Compute result bottom-up
    vector<pair<ll, int>> memo;
    for (auto& s : stack) {
        if (s.processed && s.result != 0) {
            memo.emplace_back(s.cur, s.d);
        }
    }

    // Reconstruct using recursive approach with memoization
    vector<vector<ll>> memo_table(20, vector<ll>(100000, -1));

    function<ll(ll, int)> solve = [&](ll cur, int d) -> ll {
        cur = abs(cur);
        if (cur % degs[d] == 0)
            return cur / degs[d] * d;
        if (memo_table[d][cur] != -1)
            return memo_table[d][cur];

        ll k = cur / degs[d];
        ll option1 = k * d + solve(cur - k * degs[d], d - 1);
        ll option2 = (k + 1) * d + solve((k + 1) * degs[d] - cur, d - 1);
        return memo_table[d][cur] = min(option1, option2);
    };

    cout << solve(abs(n), 18) << endl;
    return 0;
}
